pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        address ceo = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;
        address user = address(0x123);

        vm.deal(ceo, 10 ether);
        vm.prank(ceo);
        c.seedMarket{value: 1 ether}(1000);

        vm.prank(ceo);
        c.DrugDealer();

        vm.deal(user, 1 ether);
        uint256 ceoBalanceBefore = ceo.balance;
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();
        uint256 ceoBalanceAfter = ceo.balance;

        assertTrue(ceoBalanceAfter - ceoBalanceBefore == 0.04 ether);
    }
}
